#include <concepts>
#include <iostream>
template<typename T>
concept TemSaldo = requires(const T& valor) {
    { valor.saldo() } -> std::same_as<int>;
};
struct EstoqueLeitura {
    int quantidade;
    int saldo() const { return quantidade; }
};
template<TemSaldo T>
bool disponivel(const T& estoque, int quantidade) {
    return quantidade >= 0 && quantidade <= estoque.saldo();
}
int main() {
    const EstoqueLeitura estoque{3};
    static_assert(TemSaldo<EstoqueLeitura>);
    static_assert(!TemSaldo<int>);
    std::cout << std::boolalpha << disponivel(estoque, 2) << '\n';
    std::cout << disponivel(estoque, -1) << '\n';
}

