std::optional<int> quantidade(std::string_view texto) {
    if (texto.empty()) return std::nullopt;
    int valor{0};
    const auto fim = texto.data() + texto.size();
    const auto resultado = std::from_chars(texto.data(), fim, valor);
    if (resultado.ec != std::errc{} || resultado.ptr != fim || valor < 0 || valor > 1000) {
        return std::nullopt;
    }
    return valor;
}
int main() {
    for (std::string_view texto : {"12", "12x", "-1", "2000", ""}) {
        if (const auto valor = quantidade(texto)) std::cout << *valor << '\n';
