bool id_valido(const std::string& id) {
    return !id.empty() && id.size() <= 20 && std::all_of(id.begin(), id.end(), [](unsigned char ch) {
        return (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '-';
    });
}
std::map<std::string, int> restaurar(const std::string& texto) {
    std::istringstream entrada{texto};
    std::string formato;
    int versao{0};
    int quantidade{0};
    if (!(entrada >> formato >> versao >> quantidade) || formato != "CPPSTOCK" || versao != 1 || quantidade < 0 || quantidade > 1000) {
        throw std::invalid_argument("cabecalho invalido");
    }
    std::map<std::string, int> candidato;
    for (int i{0}; i < quantidade; ++i) {
        std::string id;
        int saldo{0};
        if (!(entrada >> id >> saldo) || !id_valido(id) || saldo < 0 || saldo > 1000) throw std::invalid_argument("item invalido");
        if (!candidato.emplace(id, saldo).second) throw std::invalid_argument("ID duplicado");
    }
    std::string sobra;
    if (entrada >> sobra) throw std::invalid_argument("dados extras");
    if (!entrada.eof()) throw std::invalid_argument("falha de leitura");
    return candidato;
}
int main() {
    const auto estoque = restaurar("CPPSTOCK 1 2\nA 3\nB 0\n");
    for (const auto& [id, saldo] : estoque) std::cout << id << ' ' << saldo << '\n';
}

