class Estoque {
    int saldo_{10};
    int aceitas_{0};
    std::mutex mutex_;
public:
    bool retirar(int quantidade) {
        const std::lock_guard<std::mutex> lock{mutex_};
        if (quantidade < 0 || quantidade > saldo_) return false;
        saldo_ -= quantidade;
        ++aceitas_;
        return true;
    }
    std::pair<int, int> resumo() {
        const std::lock_guard<std::mutex> lock{mutex_};
        return {saldo_, aceitas_};
    }
};
int main() {
    Estoque estoque;
    {
        std::jthread primeiro{[&] { for (int i{0}; i < 10; ++i) estoque.retirar(1); }};
        std::jthread segundo{[&] { for (int i{0}; i < 10; ++i) estoque.retirar(1); }};
    }
    const auto [saldo, aceitas] = estoque.resumo();
    std::cout << saldo << '\n' << aceitas << '\n';
}

