        const auto item = dados.find(id);
        if (item == dados.end()) return std::nullopt;
        return item->second;
    }};
    if (const auto visao = consultar.executar("OS-1")) std::cout << visao->id << ' ' << visao->estado << '\n';
    std::cout << std::boolalpha << consultar.executar("OS-2").has_value() << '\n';
