#include <iostream>
#include <map>
#include <stdexcept>
#include <string>
enum class Estado { aberta, confirmada };
struct Ordem { int quantidade; Estado estado; };
struct Resposta { std::string id; int saldo; };
struct Oficina {
    int saldo{5};
    std::map<std::string, Ordem> ordens{{"OS-1", {2, Estado::aberta}}};
    std::map<std::string, Resposta> pedidos;
};
Resposta confirmar(Oficina& oficina, const std::string& chave, const std::string& id) {
    if (chave.empty() || id.empty()) throw std::invalid_argument("chave e ID obrigatorios");
    const auto anterior = oficina.pedidos.find(chave);
    if (anterior != oficina.pedidos.end()) {
        if (anterior->second.id != id) throw std::invalid_argument("chave reutilizada");
        return anterior->second;
    }
    const auto posicao = oficina.ordens.find(id);
    if (posicao == oficina.ordens.end()) throw std::invalid_argument("ordem ausente");
    auto& ordem = posicao->second;
    int novo_saldo = oficina.saldo;
    if (ordem.estado == Estado::aberta) {
        if (ordem.quantidade < 0 || ordem.quantidade > oficina.saldo) throw std::invalid_argument("estoque insuficiente");
        novo_saldo -= ordem.quantidade;
    }
    Resposta resposta{id, novo_saldo};
    oficina.pedidos.emplace(chave, resposta);
    oficina.saldo = novo_saldo;
    ordem.estado = Estado::confirmada;
    return resposta;
}
int main() {
    Oficina oficina;
    confirmar(oficina, "pedido-1", "OS-1");
    confirmar(oficina, "pedido-1", "OS-1");
    confirmar(oficina, "pedido-2", "OS-1");
    std::cout << oficina.saldo << '\n';
    std::cout << oficina.pedidos.size() << '\n';
}

