struct Estado {
    int saldo{5};
    bool confirmada{false};
};
void confirmar(Estado& estado, const std::string& id) {
    if (id != "OS-1") throw std::invalid_argument("ordem ausente");
    if (estado.confirmada) return;
    if (estado.saldo < 2) throw std::invalid_argument("estoque insuficiente");
    estado.saldo -= 2;
    estado.confirmada = true;
}
std::string snapshot(const Estado& estado) {
    std::ostringstream saida;
    saida << "CPPFORGE 1 " << estado.saldo << ' ' << (estado.confirmada ? 1 : 0) << '\n';
    return saida.str();
}
Estado restaurar(const std::string& texto) {
    std::istringstream entrada{texto};
    std::string nome;
    int versao{0}, saldo{0}, confirmada{0};
    if (!(entrada >> nome >> versao >> saldo >> confirmada) || nome != "CPPFORGE" || versao != 1) {
        throw std::invalid_argument("snapshot invalido");
    }
    std::string sobra;
    if (entrada >> sobra || !entrada.eof()) throw std::invalid_argument("dados extras ou falha");
    if (!((confirmada == 0 && saldo == 5) || (confirmada == 1 && saldo == 3))) {
        throw std::invalid_argument("estado inconsistente");
    }
    return Estado{saldo, confirmada == 1};
}
void exibir(const Estado& estado) {
    std::cout << "OS-1 " << (estado.confirmada ? "confirmada" : "aberta") << " saldo " << estado.saldo << '\n';
}
int main(int argc, char* argv[]) {
    try {
        const std::string comando = argc > 1 ? argv[1] : "demo";
        Estado estado;
        if (comando == "demo" && argc == 1) {
            confirmar(estado, "OS-1");
            confirmar(estado, "OS-1");
            const auto copia = restaurar(snapshot(estado));
            if (copia.saldo != 3 || !copia.confirmada) throw std::logic_error("regressao");
            exibir(copia);
            std::cout << "snapshot verificado\n";
        } else if (comando == "salvar" && argc == 3) {
            const std::filesystem::path caminho{argv[2]};
            if (std::filesystem::exists(caminho)) throw std::invalid_argument("arquivo ja existe");
            confirmar(estado, "OS-1");
            std::ofstream saida{caminho};
            if (!saida) throw std::runtime_error("nao abriu arquivo");
            saida << snapshot(estado);
            saida.close();
            if (!saida) throw std::runtime_error("falha ao salvar");
            std::cout << "snapshot salvo\n";
        } else if (comando == "restaurar" && argc == 3) {
            std::ifstream entrada{argv[2], std::ios::binary};
            if (!entrada) throw std::runtime_error("nao abriu arquivo");
            std::array<char, 128> buffer{};
            entrada.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
            const auto tamanho = entrada.gcount();
            if (tamanho >= static_cast<std::streamsize>(buffer.size()) || entrada.bad() || !entrada.eof()) {
                throw std::invalid_argument("arquivo grande ou leitura incompleta");
            }
            const auto candidata = restaurar(std::string{buffer.data(), static_cast<std::size_t>(tamanho)});
            estado = candidata;
            exibir(estado);
        } else {
            throw std::invalid_argument("uso: app | app salvar arquivo | app restaurar arquivo");
        }
    } catch (const std::exception& erro) {
        std::cerr << erro.what() << '\n';
        return 1;
    }
